cases.script:
msg=$(uv --version 2>&1 >/dev/null)
st=$?
echo "status=$st"
case $msg in
  *"install it with: pkg install uv"*) echo hint-present;;
  *) echo hint-absent;;
esac
case $msg in
  *"/usr/lib/bash-os/libexec/uv/uv"*) echo names-helper-path;;
  *) echo no-helper-path;;
esac

cases.setup_script:
mkdir -p pkgroot/lib/bash-os/loadables pkgroot/lib/bash-os/libexec/uv elsewhere
cat > pkgroot/lib/bash-os/libexec/uv/uv <<'EOF'
#!/bin/sh
case "$1" in
  mask) exec /usr/bin/perl -e 'open F, "/proc/self/status" or die; while (<F>) { if (/^(SigIgn|SigCgt):\s+(\w+)/) { my $v = hex($2); printf "%s: INT=%d QUIT=%d\n", $1, ($v >> 1) & 1, ($v >> 2) & 1 } }' ;;
  term) kill -TERM $$ ;;
  kill) kill -KILL $$ ;;
  usr1) kill -USR1 $$ ;;
esac
EOF
chmod 755 pkgroot/lib/bash-os/libexec/uv/uv

mkdir -p pkgroot/lib/bash-os/loadables pkgroot/lib/bash-os/libexec/uv elsewhere
cat > pkgroot/lib/bash-os/libexec/uv/uv <<'EOF'
#!/bin/sh
case "$1" in
  mask) exec /usr/bin/perl -e 'open F, "/proc/self/status" or die; while (<F>) { if (/^(SigIgn|SigCgt):\s+(\w+)/) { my $v = hex($2); printf "%s: INT=%d QUIT=%d\n", $1, ($v >> 1) & 1, ($v >> 2) & 1 } }' ;;
  term) kill -TERM $$ ;;
