esac
EOF
chmod 755 pkgroot/lib/bash-os/libexec/uv/uv

cases.reference_script:
UVH="$PWD/pkgroot/lib/bash-os/libexec/uv/uv"
uv() { "$UVH" "$@"; }
{ uv term; echo "term=$?"; uv kill; echo "kill=$?"; uv usr1; echo "usr1=$?"; } 2>/dev/null

